+  // Compatible host mirror view
+  using host_mirror_type =
+      View<non_const_element_type, extents_type, layout_type,
+           Kokkos::Experimental::Accessor<
+               non_const_element_type,
+               typename ViewType::host_mirror_space::memory_space> >;
+};
