+    param(4) = h22;
+  } else if (flag == zero) {
+    param(2) = h21;
+    param(3) = h12;
+  } else {
+    param(1) = h11;
+    param(4) = h22;
   }
+  param(0) = flag;
 }

 template <class DXView, class YView, class PView>

